def calculate_discount(original_price, discount_percentage):
    """
    Calculate the final price of an item after applying a discount percentage.

    Parameters:
    original_price (float): The original price of the item.
    discount_percentage (float): The discount percentage to be applied.

    Returns:
    float: The final price of the item after applying the discount, rounded to two decimal places.
    """
    if discount_percentage < 0:
        discounted_price = original_price + abs((discount_percentage / 100) * original_price)
    elif discount_percentage > 100:
        discounted_price = 0.0
    else:
        discounted_price = original_price - (discount_percentage / 100) * original_price

    return round(discounted_price, 2)

