import string

def count_words(s: str) -> dict:
    """
    Processes a string to count the frequency of each word, ignoring case and punctuation.

    :param s: Input string containing words.
    :return: Dictionary with words as keys and their frequencies as values.
    """
    s = s.lower()
    s = s.translate(str.maketrans("", "", string.punctuation))
    words = s.split()
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count

# Example usage
example_string = "Hello, world! Hello, everyone."
print(count_words(example_string))  # Output: {'hello': 2, 'world': 1, 'everyone': 1}

